// Valida la petición de disponibilidad. Contrato: n8n/WEB-RESERVAS.md.
const hook = $('Webhook · GET /web-disponibilidad').first().json;
const VENTANA_MS = 10 * 60 * 1000;
const MAXIMO = 60;

const cfg = $('Config (editar por tenant)').first().json;
const tz = cfg.tenant_timezone || 'Europe/Madrid';
const headers = hook.headers || {};
const fallo = (http, motivo, extra = {}) =>
  [{ json: { _ok: false, _http: http, body: { ok: false, motivo, ...extra } } }];

// Desactivado salvo que el tenant diga qué servicio se reserva desde la web. Por defecto
// está vacío: solo el tenant de la operación de Aegora (y el de desarrollo) lo activa. Un
// cliente no tiene que encontrarse una puerta de reservas pública que nadie le ha pedido.
if (!String(cfg.servicio_web || '').trim()) return fallo(404, 'no_disponible');

// Origen permitido: ajuste WEB_ORIGENES del tenant (el de desarrollo añade el servidor
// local de Astro). Este 403 es lo que hace cumplir la regla; el CORS del webhook va abierto.
const ORIGENES = String(cfg.origenes_web || '').split(',').map(s => s.trim()).filter(Boolean);
const origen = String(headers.origin || '').trim();
if (!ORIGENES.includes(origen)) return fallo(403, 'origen_no_permitido');

// Límite por IP, en los datos estáticos del workflow (solo persisten en ejecuciones de
// producción, no al probar desde el editor). La IP es la primera de X-Forwarded-For: la
// pone Caddy, que no se fía de la que mande el cliente.
const ip = String(headers['x-forwarded-for'] || headers['x-real-ip'] || 'desconocida').split(',')[0].trim();
let _limite = 'activo';
try {
  const sd = $getWorkflowStaticData('global');
  const ahora = Date.now();
  const rl = sd.rl || {};
  for (const k of Object.keys(rl)) {
    rl[k] = rl[k].filter(t => ahora - t < VENTANA_MS);
    if (!rl[k].length) delete rl[k];
  }
  const marcas = rl[ip] || [];
  if (marcas.length >= MAXIMO) { sd.rl = rl; return fallo(429, 'demasiadas_peticiones'); }
  marcas.push(ahora);
  rl[ip] = marcas;
  sd.rl = rl;
} catch (e) {
  // Si los datos estáticos no estuvieran disponibles, la petición sigue pero queda a la
  // vista en la ejecución: una protección que no se ve no está funcionando.
  _limite = 'NO DISPONIBLE: ' + (e && e.message ? e.message : String(e));
}

const q = hook.query || {};
const hoy = DateTime.now().setZone(tz).startOf('day');
let desde = hoy;
const desdeTxt = String(q.desde || '').trim();
if (desdeTxt) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(desdeTxt)) return fallo(400, 'parametros_invalidos');
  desde = DateTime.fromISO(desdeTxt, { zone: tz });
  if (!desde.isValid || desde < hoy) return fallo(400, 'parametros_invalidos');
}
let dias = 14;
const diasTxt = String(q.dias ?? '').trim();
if (diasTxt) {
  dias = Number(diasTxt);
  if (!Number.isInteger(dias) || dias < 1 || dias > 31) return fallo(400, 'parametros_invalidos');
}
const fechas = [];
for (let i = 0; i < dias; i++) fechas.push(desde.plus({ days: i }).toFormat('yyyy-LL-dd'));
return [{ json: { _ok: true, _limite, ip, fechas, tz } }];

// Un item por día: el nodo HTTP de después hace una consulta al Booking API por cada uno.
// Llamarle directamente y no a `APPOINTMENT Availability` ahorra un sub-workflow por día.
const v = $('Code · Validar').first().json;
const r = $json ?? {};
const filas = (r.body && r.body.data) || [];
if ((r.statusCode ?? 0) >= 300 || filas.length !== 1) {
  return [{ json: { _ok: false, _http: 503, body: { ok: false, motivo: 'no_disponible' },
    _causa: filas.length > 1 ? 'hay varios servicios activos con ese nombre'
                             : 'servicio no encontrado o Directus no responde',
    _status_directus: r.statusCode ?? null } }];
}
return v.fechas.map(fecha => ({ json: { _ok: true, fecha, service_id: filas[0].id, tz: v.tz } }));

// Respuesta pública: fechas, horas y plazas. Nada de ids de recurso ni de servicio.
const tz = $('Code · Validar').first().json.tz;
const svc = $('HTTP · Servicio').first().json.body.data[0];
const label = f => DateTime.fromISO(f, { zone: tz }).setLocale('es').toFormat("cccc d 'de' LLLL");
const dias = [];
let errores = 0;
for (const it of $input.all()) {
  const r = it.json ?? {};
  const b = r.body || {};
  if ((r.statusCode ?? 0) >= 300 || b.ok !== true) { errores += 1; continue; }
  const huecos = (b.slots || []).map(s => ({
    inicio: s.start_at,
    hora: DateTime.fromISO(s.start_at, { setZone: true }).setZone(tz).toFormat('HH:mm'),
    plazas: s.seats_left,
  }));
  if (huecos.length) dias.push({ fecha: b.date, fecha_label: label(b.date), huecos });
}
// Un día que falla no se esconde: una lista con huecos de menos parecería una agenda llena.
if (errores) return [{ json: { _http: 503, body: { ok: false, motivo: 'no_disponible' }, _dias_con_error: errores } }];
dias.sort((a, b) => (a.fecha < b.fecha ? -1 : 1));
return [{ json: { _http: 200, body: { ok: true,
  servicio: { nombre: svc.name, duracion_minutos: svc.duration_minutes }, zona: tz, dias } } }];
